    windowText: v => `Read the black rotor letters in the yellow window from the centre out: left, middle, right. Set {{${v.start}}}: left rotor to {{${v.start[0]}}}, middle to {{${v.start[1]}}}, right to {{${v.start[2]}}}. To turn a rotor means: so that the next letter shows in the window.`,

    plugOver: 'PLUGBOARD', plugTitle: 'Cables swap letters',
    plugIntro: v => { const [a, b] = v.cable0; return `The front of the Enigma had 26 sockets, laid out like the keyboard. A cable plugged into two sockets swaps two letters, both ways: the ${a}–${b} cable turns ${a} into ${b} and ${b} into ${a}. A letter without a cable goes straight through. Today there are ${v.nCables} cables: {{${v.plug}}}.`; },
